// Client-safe helpers for the Destinations map. The outline and projection constants come from
// src/data/philippines-map.json, generated by `npm run map` (scripts/build-map.mjs).
import MAP from "@/data/philippines-map.json";

export type IslandGroupKey = "luzon" | "visayas" | "mindanao" | "palawan";

export const PH_MAP = MAP as {
  viewBox: [number, number, number, number];
  project: { lng0: number; lat0: number; kx: number; ky: number; pad: number };
  groups: Record<IslandGroupKey, string>;
  bbox: Record<IslandGroupKey, [number, number, number, number]>;
};

// [lat, lng] → SVG coordinates in the map's viewBox (same equirectangular projection as the outline).
export function project([lat, lng]: [number, number]) {
  const p = PH_MAP.project;
  return { x: p.pad + (lng - p.lng0) * p.kx, y: p.pad + (p.lat0 - lat) * p.ky };
}
